<template><fieldset class="theme-switcher" aria-describedby="theme-status"><legend class="visually-hidden">Оформление</legend><label v-for="item in choices" :key="item.value"><input v-model="preference" type="radio" name="theme" :value="item.value" @change="change" /><span>{{ item.label }}</span></label><span id="theme-status" class="visually-hidden" aria-live="polite">{{ status }}</span></fieldset></template><script setup>import { computed, ref } from 'vue'; import { useTheme } from '../composables/useTheme'; const { preference, setTheme } = useTheme(); const choices = [{value:'system',label:'Система'},{value:'light',label:'Светлая'},{value:'dark',label:'Тёмная'}]; const status = ref(''); const change = () => { const actual = setTheme(preference.value); status.value = `Выбрана тема: ${choices.find((x) => x.value === preference.value).label}; активна ${actual === 'dark' ? 'тёмная' : 'светлая'} палитра.`; };</script>
